/**
 * THE 37 PER-TICK ENTRIES, READ (2026-08-14).
 *
 * Companion audit, one row per entry in plain English:
 * `build/proposed-curated/per-tick-reading.json`, regenerated by
 * `node scripts/extract/per-tick-audit.ts`.
 *
 * DATA-SOURCES §58 withdrew 37 ability entries to `incomplete` because a component of each states
 * a PER-TICK damage figure and nobody had read the sentence behind it. The label alone cannot
 * decide the question: `per Arrow`, `per Bullet`, `per Spin` and `per Wave` are the same field and
 * the opposite meaning — hits that land in one moment, which belong in the burst total.
 *
 * This file is the reading. One entry per withdrawn ability, each carrying:
 *   - `quote`     — the sentence the verdict rests on, in readable English.
 *   - `verbatim`  — the SAME sentence as it appears in the cached wikitext, markup and all.
 *                   `verifyQuotes()` proves every one of these is a literal substring of
 *                   `build/proposed-curated/ability-wikitext.json`, so a quote cannot be
 *                   paraphrased into saying something the source does not.
 *   - the arithmetic: the duration and the interval the source states, the tick count they imply,
 *     and the count actually stored in `hits`.
 *
 * TWO SEPARATE QUESTIONS, AND THEY ARE NOT ANSWERED TOGETHER.
 *
 *   1. IS IT RECURRING? Decided by the sentence. All 37 are — every one states an interval in
 *      seconds. Not one turned out to be the `per Arrow` shape. That is the finding.
 *   2. IS THE STORED COUNT A FULL-DURATION COUNT? A separate, stored fact, and 18 of the 37 fail
 *      it. `marked` is true only when BOTH hold.
 *
 * Why the second question gates the first. Marking a component moves its figure out of the burst
 * line and into the damage-over-time line — where the engine multiplies it by `hits` and states it
 * as the total across the full duration (SPECIFICATION §3.8). Gate 1 requires a count and `hits: 1`
 * satisfies it, so marking an entry whose real count is 30 would publish a thirtieth of the damage
 * as the whole burn. That is a plausible wrong number, which is the one outcome this project
 * exists to prevent. An entry that recurs but cannot state its count stays withdrawn, and the
 * reason travels with it.
 *
 * ADDING A MEMBER MEANS READING ITS SENTENCE. This table is not a pattern and must never become
 * one: a new member is a new row with its own quote, checked against the cache.
 */

import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
/** Repo root. */
export const ROOT = join(HERE, '..', '..');

/** Where the source sentences were cached. Read-only here; the harvester owns writing it. */
export const WIKITEXT_CACHE = 'build/proposed-curated/ability-wikitext.json';

/** Why a read entry is not marked as recurring even though its sentence says it recurs. */
export type CountVerdict =
  /** The source's duration divided by its interval equals the stored `hits`. Safe to mark. */
  | 'corroborated'
  /** The source states no duration at all — a toggle, an aura, a resource-fed channel. */
  | 'no-duration-stated'
  /** A duration and interval are stated, so a count exists, but `hits` is 1: it was never stored. */
  | 'count-not-stored'
  /** The source's own description and its own leveling row imply DIFFERENT counts. */
  | 'contested';

export interface PerTickRead {
  /** `champion/slot/abilityName`, the same key merge-proposal.ts uses. */
  key: string;
  /** RECURRING for all 37. Kept as a field so a future member cannot skip stating it. */
  verdict: 'recurring' | 'simultaneous' | 'source-silent';
  countVerdict: CountVerdict;
  /** The sentence, readable. This is what lands in `overTime.sourceSays` for a marked entry. */
  quote: string;
  /** The same sentence(s) as literal substrings of the cached wikitext. Checked, not trusted. */
  verbatim: string[];
  /** Seconds the source gives for the effect's duration; null when it states none. */
  durationSeconds: number | null;
  /** Seconds between ticks, as the source states it. */
  intervalSeconds: number;
  /** duration / interval, where both exist. */
  impliedTicks: number | null;
  /** What `hits` actually holds in the harvested entry today. */
  storedHits: number[];
  /** True only when verdict is 'recurring' AND countVerdict is 'corroborated'. */
  marked: boolean;
  /** Anything a reader of this table needs that the quote does not carry. */
  note?: string;
}

