/** The entries this reading marks as recurring, as `key -> the sentence it rests on`. */
export function markedOverTime(): ReadonlyMap<string, string> {
  return new Map(PER_TICK_READS.filter((r) => r.marked).map((r) => [r.key, r.quote]));
}

/**
 * A MARKED ROW MUST BE RECURRING AND ITS COUNT CORROBORATED. Nothing else may be marked.
 *
 * The rule the table is written to, restated as a check so a later edit cannot quietly break it:
 * marking a row whose count is contested or unstored publishes a wrong burn total.
 */
export function checkMarkRule(reads: readonly PerTickRead[] = PER_TICK_READS): string[] {
  const wrong: string[] = [];
  for (const r of reads) {
    const eligible = r.verdict === 'recurring' && r.countVerdict === 'corroborated';
    if (r.marked && !eligible) {
      wrong.push(`${r.key}: marked, but it is ${r.verdict} with a ${r.countVerdict} count`);
    }
    if (!r.marked && eligible) {
      wrong.push(`${r.key}: recurring with a corroborated count, but not marked`);
    }
    if (r.marked && !r.quote) wrong.push(`${r.key}: marked with no quote`);
    if (r.countVerdict === 'corroborated' && r.impliedTicks !== r.storedHits[0]) {
      wrong.push(
        `${r.key}: called corroborated, but ${r.durationSeconds}s / ${r.intervalSeconds}s = ` +
          `${r.impliedTicks} and hits is ${r.storedHits[0]}`,
      );
    }
  }
  return wrong;
}

/** The four read before these 37 (DATA-SOURCES §58.3). Not part of this reading. */
export const ALREADY_READ: ReadonlySet<string> = new Set([
  'Fizz/W/Seastone Trident',
  'Teemo/E/Toxic Shot',
  'Teemo/R/Noxious Trap',
  'Nilah/R/Apotheosis',
]);

/** The same test merge-proposal.ts uses to find a per-tick component. */
export const PER_TICK_LABEL = /per\s*tick/i;

/** The shape this table needs from a harvested ability. Narrower than `CuratedAbility` on purpose:
 *  the reading depends on identity, the component labels and the hit counts, and on nothing else. */
export interface HarvestedShape {
  champion: string;
  slot: string;
  abilityName: string;
  components: Array<{ label?: string | undefined; hits?: number | undefined }>;
}

/**
 * THE TABLE MUST DESCRIBE THE REAL POPULATION, NOT A REMEMBERED ONE.
 *
 * Three ways a hand-read table goes wrong once the data moves under it, and all three are worse
 * than having no table, because a stale row reads exactly like a checked one:
 *   - an entry acquires a per-tick component and nobody reads it;
 *   - a row survives for an entry that no longer has one;
 *   - a hit count changes and the arithmetic in the row now describes nothing.
 */
export function checkAgainstHarvest(
  reads: readonly PerTickRead[],
  abilities: readonly HarvestedShape[],
): string[] {
  const out: string[] = [];
  const id = (a: HarvestedShape): string => `${a.champion}/${a.slot}/${a.abilityName}`;
  const population = abilities.filter(
    (a) => a.components.some((c) => PER_TICK_LABEL.test(c.label ?? '')) && !ALREADY_READ.has(id(a)),
  );
  const tableKeys = new Set(reads.map((r) => r.key));
  for (const a of population) {
    if (!tableKeys.has(id(a))) out.push(`${id(a)}: carries a per-tick component and nobody read it`);
  }
  for (const k of tableKeys) {
    if (!population.some((a) => id(a) === k)) out.push(`${k}: read, but it is not in the population`);
  }
  for (const r of reads) {
    const a = population.find((x) => id(x) === r.key);
    if (!a) continue;
    const actual = a.components
      .filter((c) => PER_TICK_LABEL.test(c.label ?? ''))
      .map((c) => c.hits ?? null);
    if (JSON.stringify(actual) !== JSON.stringify(r.storedHits)) {
      out.push(
        `${r.key}: the reading says hits ${JSON.stringify(r.storedHits)}, the harvest holds ` +
          `${JSON.stringify(actual)}`,
      );
    }
  }
  return out;
}

export interface QuoteCheck {
  key: string;
  found: number;
  missing: string[];
  pageMissing: boolean;
}

/** A cached source page, as `ability-wikitext.json` stores it. */
export interface CachedPage {
  champion: string;
  slot: string;
  abilityName: string;
  wikitext: string;
}

/**
 * PROVE EVERY QUOTE IS REALLY IN THE SOURCE.
 *
 * Each `verbatim` fragment must appear as a literal substring of the ability's cached wikitext.
 * A paraphrase that drifted, or a sentence attributed to the wrong ability, fails here.
 */
export function verifyQuotes(
  reads: readonly PerTickRead[],
  pages: readonly CachedPage[],
): QuoteCheck[] {
  const byKey = new Map(pages.map((p) => [`${p.champion}/${p.slot}/${p.abilityName}`, p.wikitext]));
  return reads.map((r) => {
    const text = byKey.get(r.key);
    if (text === undefined) return { key: r.key, found: 0, missing: r.verbatim, pageMissing: true };
    const missing = r.verbatim.filter((v) => !text.includes(v));
    return { key: r.key, found: r.verbatim.length - missing.length, missing, pageMissing: false };
  });
}

/** Read the wikitext cache. Separated from `verifyQuotes` so the check itself needs no disk. */
export async function loadPages(): Promise<CachedPage[]> {
  const raw = await readFile(join(ROOT, WIKITEXT_CACHE), 'utf8');
  return (JSON.parse(raw) as { pages: CachedPage[] }).pages;
}
